mapper.select:
SELECT c.id AS companyId, #{statDate} AS statDate, #{statType} AS statType, COALESCE(SUM(CASE WHEN sr.scan_type = 4 THEN 1 ELSE 0 END), 0) AS fillCount, COALESCE(SUM(CASE WHEN sr.scan_type = 5 THEN 1 ELSE 0 END), 0) AS inspectionCount, COALESCE(SUM(CASE WHEN sr.scan_type = 3 THEN 1 ELSE 0 END), 0) AS inCount, COALESCE(SUM(CASE WHEN sr.scan_type = 2 THEN 1 ELSE 0 END), 0) AS outCount FROM company c LEFT JOIN scan_record sr ON sr.company_id = c.id
AND sr.scan_time >= #{startTime}
AND sr.scan_time < #{endTime}
GROUP BY c.id
